Definition locals (M : word -> option byte) : Prop :=
  L5.u64_at RSEGS M (S - 184) len /\ L5.u64_at RSEGS M (S - 176) ((os + 256) / 8 + 2147450880) /\ L5.u64_at RSEGS M (S - 168) (os + 256)
